@namespace sv_213222b20f924e6392cd32227dfb3234.Components.Pages.Settings
@using sv_213222b20f924e6392cd32227dfb3234.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading-text">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            @theme
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            @size
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Language</h3>
                <select @bind="_language" class="form-control">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Key">@lang.Value</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_compactMode" class="toggle-input" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <div class="live-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p>Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "Yes" : "No")</p>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_successMessage is not null)
            {
                <div class="toast toast-success">@_successMessage</div>
            }
        </div>
    }
</div>

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly Dictionary<string, string> _languages = new()
    {
        ["en"] = "English",
        ["es"] = "Spanish",
        ["fr"] = "French",
        ["de"] = "German",
        ["ja"] = "Japanese",
        ["zh"] = "Chinese"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
            "Light" => "background-color: #ffffff; color: #333333;",
            _ => "background-color: #f5f5f5; color: #444444;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.2rem;",
            _ => "font-size: 1rem;"
        };

        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";

        return $"{bg} {font} {padding} border-radius: 8px; border: 1px solid #ddd; margin-top: 1rem;";
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _successMessage = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

