.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background-color: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.2s, border-left 0.2s;
    border-left: 3px solid transparent;
    color: #555;
}

.settings-nav-item:hover {
    background-color: #e9ecef;
}

.settings-nav-item.active {
    background-color: #e3f2fd;
    border-left-color: #1976d2;
    color: #1976d2;
    font-weight: 600;
}

.settings-nav-icon {
    margin-right: 0.75rem;
    font-size: 1.2rem;
}

.settings-nav-label {
    font-size: 0.95rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

/* Form controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #555;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

/* Buttons */
.btn {
    padding: 0.55rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background-color 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background-color: #1976d2;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1565c0;
}

.btn-secondary {
    background-color: #e0e0e0;
    color: #333;
}

.btn-secondary:hover:not(:disabled) {
    background-color: #d0d0d0;
}

.btn-danger {
    background-color: #d32f2f;
    color: white;
}

.btn-danger:hover:not(:disabled) {
    background-color: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
}

.toast-success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background-color: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
    margin-bottom: 0.5rem;
    display: block;
    margin-left: auto;
    margin-right: auto;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: #888;
    word-break: break-all;
}

/* Toggle switch */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-input {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channel list */
.muted-channels {
    margin-top: 1.5rem;
}

.muted-channels h3 {
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    padding: 0;
}

.channel-item {
    padding: 0.4rem 0;
}

.channel-item label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

