    font-size: 0.85rem;
    text-transform: uppercase;
    color: #666;
}

.current-session-badge {
    font-size: 0.8rem;
    background-color: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

/* Confirmation dialog */
.confirmation-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.confirmation-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Live preview */
.live-preview {
    margin-top: 1.5rem;
    transition: all 0.3s ease;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

/* Loading */
.loading-text {
    color: #888;
    font-style: italic;
}

